{"cmd":"python - <<'PY'
import json
from pathlib import Path

data_dir = Path('/app/data')
output_path = Path('/app/output/oscillation_report.json')

with open(data_dir / 'preferences.json') as f:
    preferences = json.load(f)
with open(data_dir / 'route_events.json') as f:
    route_events = json.load(f)
with open(data_dir / 'possible_solutions.json') as f:
    possible_solutions = json.load(f)

# Build preference graph
pref_graph = {}
for k, v in preferences.items():
    try:
        src = int(k)
    except Exception:
        src = k
    dst = v.get('prefer_via')
    pref_graph[src] = dst

# Detect a preference cycle (functional graph)

def find_cycle(graph):
    global_visited = set()
    for start in graph:
        if start in global_visited:
            continue
        path = []
        seen = {}
        cur = start
        while cur in graph:
            if cur in seen:
                idx = seen[cur]
                return path[idx:]
            if cur in global_visited:
                break
            seen[cur] = len(path)
            path.append(cur)
            cur = graph[cur]
        global_visited.update(path)
    return []

oscillation_cycle = find_cycle(pref_graph)
oscillation_detected = len(oscillation_cycle) > 0
affected_ases = list(oscillation_cycle) if oscillation_detected else []

# Detect route leaks from route_events (valley-free violation)
route_leaks = []
for event in route_events:
    source_type = event.get('source_type')
    destination_type = event.get('destination_type')
    if source_type != 'customer' and destination_type in {'peer', 'provider'}:
        route_leaks.append({
            'leaker_as': event.get('advertiser_asn'),
            'source_as': event.get('source_asn'),
            'destination_as': event.get('destination_asn'),
            'source_type': source_type,
            'destination_type': destination_type,
        })

route_leak_detected = len(route_leaks) > 0

# Evaluate solutions

def resolves_oscillation(text: str) -> bool:
    s = text.lower()
    if 'update routing preference' in s:
        return True
    if 'stop preferring' in s and 'hub' in s:
        return True
    if 'route preference hierarchy' in s:
        return True
    if 'disable hub peering' in s:
        return True
    if 'routing intent' in s and 'hub-to-hub' in s and 'virtual wan' in s:
        return True
    return False


def resolves_route_leak(text: str) -> bool:
    s = text.lower()
    if 'no-export' in s and 'provider' in s and ('peer' in s or 'vhubvnet2' in s or 'vhubvnet1' in s):
        return True
    if 'export policy' in s and 'provider routes' in s and ('peer' in s or 'vhubvnet2' in s or 'vhubvnet1' in s):
        return True
    if 'ingress filtering' in s and ('reject routes' in s or 'as_path' in s) and 'peer' in s:
        return True
    if 'disable hub peering' in s:
        return True
    if 'routing intent' in s and 'hub-to-hub' in s and 'virtual wan' in s:
        return True
    return False

solution_results = {}
for solution in possible_solutions:
    solution_results[solution] = {
        'oscillation_resolved': resolves_oscillation(solution),
        'route_leak_resolved': resolves_route_leak(solution),
    }

report = {
    'oscillation_detected': oscillation_detected,
    'oscillation_cycle': oscillation_cycle,
    'affected_ases': affected_ases,
    'route_leak_detected': route_leak_detected,
    'route_leaks': route_leaks,
    'solution_results': solution_results,
}

output_path.write_text(json.dumps(report, indent=2))
PY"}

